expand_details.cypher:
MATCH (start:api {name: 'POST /api/v1/travelservice/trips'})
CALL apoc.path.expandConfig(start, {
    sequence: 'api,provides,service,targets,pod,hosts,node,has,socket',
    minLevel: 0,
    maxLevel: 4,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;
